  function applyCustomCss(css,enabled=true){let node=$('lrSpaceCustomCssStyle');if(!node){node=document.createElement('style');node.id='lrSpaceCustomCssStyle';document.head.appendChild(node)}node.textContent=enabled?scopeCustomCss(css):'';return node.textContent}
  function openCustomCss(){ensureScreens();let raw='';try{raw=localStorage.getItem(SPACE_CSS_KEY)||''}catch(e){}$('lrSpaceCustomCssInput').value=raw;$('lrSpaceCssEnabled').checked=localStorage.getItem(SPACE_CSS_KEY+':enabled')!=='false';$('lrSpaceCustomCssStatus').textContent=raw?'已读取本机保存的 CSS。':'尚未设置自定义 CSS。';showScreen('lrSpaceStoryCssEditor')}
